CREATE FUNCTION public.aviv_reorder_content(_kind text,_id uuid,_direction integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; pos integer; target integer; n integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _kind NOT IN ('services','faqs') OR _direction NOT IN (-1,1) THEN RAISE EXCEPTION 'Invalid ordering request'; END IF; PERFORM pg_advisory_xact_lock(7312404); IF _kind='services' THEN SELECT array_agg(id ORDER BY sort_order,id) INTO ids FROM public.services; ELSE SELECT array_agg(id ORDER BY sort_order,id) INTO ids FROM public.faqs; END IF; pos=array_position(ids,_id); IF pos IS NULL THEN RAISE EXCEPTION 'Content not found'; END IF; target=pos+_direction; IF target<1 OR target>array_length(ids,1) THEN RETURN; END IF; ids[pos]=ids[target]; ids[target]=_id; FOR n IN 1..array_length(ids,1) LOOP IF _kind='services' THEN UPDATE public.services SET sort_order=n-1 WHERE id=ids[n] AND sort_order<>n-1; ELSE UPDATE public.faqs SET sort_order=n-1 WHERE id=ids[n] AND sort_order<>n-1; END IF; END LOOP; END $$; REVOKE ALL ON FUNCTION public.aviv_reorder_content(text,uuid,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.aviv_reorder_content(text,uuid,integer) TO authenticated,service_role;